#Requires -Version 7.0
<#
.SYNOPSIS
    Runs the text of a local PowerShell script on PAYTON-LEGION2 as kingd over the operator's SSH route
    (MEMORY-INFRA-001: ssh alias LEGION2, key authentication, no password) and prints the output. The script
    is parsed locally first and sent as an encoded command, so no quoting crosses the shell boundary.
    Supports -WhatIf (prints the script, sends nothing).
.PARAMETER ScriptPath
    Local .ps1 file whose content runs remotely.
.PARAMETER OutFile
    Optional local file that also receives the output.
.PARAMETER SupportFiles
    Optional local files copied (scp) into kingd's temp folder before the script runs; each must parse without
    errors, and its SHA-256 is printed so the remote script can verify it.
.PARAMETER RemoteArgumentLine
    Optional arguments for the remote script as one space-separated line of literal tokens; each token must match
    ^[A-Za-z0-9._:/=,-]+$ so no quoting or shell syntax crosses the SSH and cmd.exe boundary.
#>
[CmdletBinding(SupportsShouldProcess)]
param(
    [Parameter(Mandatory)] [string] $ScriptPath,
    [string] $OutFile = '',
    [string[]] $SupportFiles = @(),
    [string] $RemoteArgumentLine = ''
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$resolved = (Resolve-Path -LiteralPath $ScriptPath).Path
$tokens = $null
$parseErrors = $null
$null = [System.Management.Automation.Language.Parser]::ParseFile($resolved, [ref]$tokens, [ref]$parseErrors)
if (@($parseErrors).Count -gt 0) { throw "Remote script has $(@($parseErrors).Count) parse errors; not sent." }
$remote = Get-Content -LiteralPath $resolved -Raw
$RemoteArguments = @($RemoteArgumentLine.Split(' ', [StringSplitOptions]::RemoveEmptyEntries))
foreach ($argument in $RemoteArguments) {
    if ($argument -notmatch '^[A-Za-z0-9._:/=,-]+$') { throw "Remote argument '$argument' is not a plain literal token; not sent." }
}
$support = foreach ($file in $SupportFiles) {
    $supportPath = (Resolve-Path -LiteralPath $file).Path
    $null = [System.Management.Automation.Language.Parser]::ParseFile($supportPath, [ref]$tokens, [ref]$parseErrors)
    if (@($parseErrors).Count -gt 0) { throw "Support file $supportPath has $(@($parseErrors).Count) parse errors; not sent." }
    [pscustomobject]@{ Path = $supportPath; Sha256 = (Get-FileHash -LiteralPath $supportPath -Algorithm SHA256).Hash }
}
# Operator 2026-10-20: the lab link is a direct wire on 10.42.0.0/24; use IP addresses, not hostnames. The alias
# keeps its user and key; the host key is still checked against the name it was stored under.
$route = @('-o', 'HostName=10.42.0.143', '-o', 'HostKeyAlias=PAYTON-LEGION2')
if (-not $PSCmdlet.ShouldProcess('PAYTON-LEGION2 (kingd over SSH)', "Run $resolved")) {
    foreach ($item in @($support)) { "WHATIF support file $($item.Path) sha256=$($item.Sha256)" }
    "WHATIF remote arguments: $($RemoteArguments -join ' ')"
    'WHATIF remote script follows:'
    $remote
    return
}
foreach ($item in @($support)) {
    & scp -q -o BatchMode=yes @route $item.Path ('LEGION2:C:/Users/kingd/AppData/Local/Temp/' + (Split-Path -Leaf $item.Path))
    if ($LASTEXITCODE -ne 0) { throw "scp of support file $($item.Path) failed with exit $LASTEXITCODE" }
    "LOCAL SUPPORT $($item.Path) sha256=$($item.Sha256)"
}

# The remote default shell is cmd.exe (8191-character command line), so the script is copied to kingd's
# temp folder with scp, run with pwsh -File, and that one copy is removed afterwards.
$remoteName = 'mcp-ssh-' + [guid]::NewGuid().ToString('N') + '.ps1'
$remoteWinPath = 'C:\Users\kingd\AppData\Local\Temp\' + $remoteName
"LOCAL START $((Get-Date).ToString('s')) script=$resolved remote=$remoteWinPath"
& scp -q -o BatchMode=yes @route $resolved ('LEGION2:C:/Users/kingd/AppData/Local/Temp/' + $remoteName)
if ($LASTEXITCODE -ne 0) { throw "scp failed with exit $LASTEXITCODE" }
$argumentText = if ($RemoteArguments.Count -gt 0) { ' ' + ($RemoteArguments -join ' ') } else { '' }
# A long target prints nothing while it runs; keepalives tolerate up to ten minutes without a server reply
# (2026-10-20 09:42: the default dropped a silent Test run after two minutes; the remote run kept going).
$lines = & ssh -o BatchMode=yes -o ServerAliveInterval=15 -o ServerAliveCountMax=40 @route LEGION2 "pwsh -NoProfile -NonInteractive -File $remoteWinPath$argumentText" 2>&1 | ForEach-Object { [string]$_ }
$exitCode = $LASTEXITCODE
$null = & ssh -o BatchMode=yes @route LEGION2 "pwsh -NoProfile -NonInteractive -Command Remove-Item -LiteralPath $remoteWinPath" 2>&1
$lines
"LOCAL END $((Get-Date).ToString('s')) ssh exit=$exitCode"
if ($OutFile) {
    $header = "RECEIPT $((Get-Date).ToString('s')) host=PAYTON-LEGION2 route=ssh-kingd script=$resolved exit=$exitCode"
    Set-Content -LiteralPath $OutFile -Value (@($header) + @($lines)) -Encoding utf8
    "LOCAL SAVED $OutFile lines=$(@($lines).Count)"
}
if ($exitCode -ne 0) { exit $exitCode }

