3: namespace QBrainAi.Tests.Shared;
4: 
5: /// <summary>
6: /// TR-MCP-USECASE-018 (AC-006), TR-MCP-USECASE-019 (AC-008): the one repository-root locator for the unit-test
7: /// projects, linked into each project that reads the checkout, so every test that reads repository files reaches
8: /// it. Reading the checkout is an environment dependence (operator 2026-10-19: "If it depends on the environment,
9: /// it's an integration test."), so the locator resolves only inside a test case, or a test-class fixture, tagged
10: /// <c>[Trait("Category", "Integration")]</c>; a unit test that reaches it fails with the reason, which makes the
11: /// full unit run the proof that no unit test reads the repository. The root comes from <c>MCP_REPOSITORY_ROOT</c>,
12: /// then the <c>McpRepositoryRoot</c> build metadata, then the first directory above the test assembly, the test
13: /// output or the current directory that holds the repository markers (<c>.git</c>, <c>QBrainAi.sln</c>,
14: /// <c>Directory.Build.props</c>).
15: /// </summary>
16: internal static class TestRepositoryRoot
17: {
18:     private const string RuleMessage =
19:         "A unit test may not read the repository checkout: it depends on the environment, so it is an integration "
20:         + "test. Tag the test method or its class [Trait(\"Category\", \"Integration\")], or read a fixture copied "
21:         + "to the test output.";
22: 
23:     private static readonly Lazy<string> Located = new(Locate, LazyThreadSafetyMode.ExecutionAndPublication);
24: 
25:     /// <summary>The repository root; resolves only for an integration test or its class fixture.</summary>
26:     internal static string Resolve()
27:     {
28:         EnsureIntegration(TestContext.Current.TestCase?.Traits ?? TestContext.Current.TestClass?.Traits);
29:         return Located.Value;
30:     }
31: 
32:     /// <summary>
33:     /// The <c>McpRepositoryRoot</c> build metadata of the test assembly (TR-MCP-USECASE-018: the deterministic
34:     /// repository-root anchor), or null when the project does not embed it; available only for an integration test
35:     /// or its class fixture, since the value names the checkout.
36:     /// </summary>
37:     internal static string? BuildMetadataRoot
38:     {
39:         get
40:         {
41:             EnsureIntegration(TestContext.Current.TestCase?.Traits ?? TestContext.Current.TestClass?.Traits);
42:             return ReadBuildMetadata();
43:         }
44:     }
45: 
46:     /// <summary>A path under the repository root; resolves only for an integration test or its class fixture.</summary>
47:     /// <param name="segments">Path segments below the root.</param>
48:     internal static string Combine(params string[] segments)
49:     {
50:         ArgumentNullException.ThrowIfNull(segments);
51:         return Path.Combine(new[] { Resolve() }.Concat(segments).ToArray());
52:     }
53: 
54:     /// <summary>
55:     /// The trait policy shared by <see cref="Resolve"/> and its mock tests: passes only when the traits hold
56:     /// <c>Category=Integration</c>; otherwise, including when there is no test context, throws naming the rule.
57:     /// </summary>
58:     /// <param name="traits">The running test case's or test class's traits, or null outside a test.</param>
59:     internal static void EnsureIntegration(IReadOnlyDictionary<string, IReadOnlyCollection<string>>? traits)
60:     {
61:         if (traits is not null
62:             && traits.TryGetValue("Category", out var categories)
63:             && categories.Contains("Integration", StringComparer.Ordinal))
64:         {
65:             return;
66:         }
67: 
68:         throw new InvalidOperationException(RuleMessage);
69:     }
70: 
71:     private static string Locate()
72:     {
73:         var configured = Environment.GetEnvironmentVariable("MCP_REPOSITORY_ROOT");
74:         if (!string.IsNullOrWhiteSpace(configured))
75:             return Validate(configured, "Configured");
76: 
77:         var buildRoot = ReadBuildMetadata();
78:         if (!string.IsNullOrWhiteSpace(buildRoot))
79:             return Validate(buildRoot, "Build-metadata");
80: 
81:         var startingPoints = new[]
82:         {
83:             Path.GetDirectoryName(typeof(TestRepositoryRoot).Assembly.Location),
84:             AppContext.BaseDirectory,
85:             Directory.GetCurrentDirectory(),
86:         };
87:         foreach (var startingPoint in startingPoints.Where(candidate => !string.IsNullOrWhiteSpace(candidate)))
88:         {
89:             for (var current = new DirectoryInfo(Path.GetFullPath(startingPoint!)); current is not null; current = current.Parent)
90:             {
91:                 if (IsRepositoryRoot(current.FullName))
92:                     return current.FullName;
93:             }
94:         }
95: 
96:         throw new InvalidOperationException(
97:             "Repository root was not found from MCP_REPOSITORY_ROOT, build metadata, the test assembly, the test output, "
98:             + "or the current directory.");
99:     }
100: 
101:     private static string? ReadBuildMetadata() =>
102:         typeof(TestRepositoryRoot).Assembly
103:             .GetCustomAttributes<AssemblyMetadataAttribute>()
104:             .FirstOrDefault(attribute => string.Equals(attribute.Key, "McpRepositoryRoot", StringComparison.Ordinal))
105:             ?.Value;
106: 
107:     /// <summary>Validates an explicit root without falling back to another checkout.</summary>
108:     private static string Validate(string candidate, string source)
109:     {
110:         var root = Path.GetFullPath(candidate);
111:         if (!IsRepositoryRoot(root))
112:             throw new InvalidOperationException($"{source} repository root is invalid: {root}");
113: 
114:         return root;
115:     }
116: 
117:     private static bool IsRepositoryRoot(string root)
118:     {
119:         var gitMarker = Path.Combine(root, ".git");
120:         return (File.Exists(gitMarker) || Directory.Exists(gitMarker))
121:             && File.Exists(Path.Combine(root, "QBrainAi.sln"))
122:             && File.Exists(Path.Combine(root, "Directory.Build.props"));
123:     }
124: }

