7: /// <summary>
8: /// TR-MCP-USECASE-018 (AC-006), TR-MCP-USECASE-019 (AC-008): finds platform dependence in unit tests by reading
9: /// the C# syntax tree. A test that depends on the platform is an integration test (operator 2026-10-19: "If it
10: /// depends on the environment, it's an integration test."), so an operating-system check, an OS-platform
11: /// attribute, an xUnit skip, or a binding to the real process host is a finding unless the test method, its
12: /// test class, or an enclosing class carries <c>[Trait("Category", "Integration")]</c>. The compiler's parser
13: /// separates code from strings, comments and documentation and keeps the code inside interpolation holes, so a
14: /// member access split across lines, a qualified, global-qualified or aliased name, a <c>using static</c>
15: /// import, a method group, and an attribute anywhere in an attribute list are read like a plain call or
16: /// attribute; a name inside <c>nameof</c> is not a use. Aliases and static imports resolve in the lexical scope
17: /// of the code that uses them, as the compiler resolves them: the file's directives, then each enclosing
18: /// namespace's, an inner alias hiding an outer one, so a directive in one namespace does not reach another. Every conditional-compilation branch is read: the file
19: /// is parsed once for each combination of the symbols its <c>#if</c> and <c>#elif</c> directives name, and a
20: /// file that names more than <see cref="MaxConditionalSymbols"/> symbols fails the scan instead of leaving a
21: /// branch unread. Test classes are types whose name ends in <c>Tests</c> or that declare a method with an
22: /// attribute whose name ends in <c>Fact</c> or <c>Theory</c>; other helper types (for example the host-neutral
23: /// <c>UnitTestPaths</c> fixture) are not test classes. An OS-platform attribute on the assembly or module is a
24: /// finding for the whole project. Limits: the scan reads one file's syntax, so dependence reached through a
25: /// helper type defined in another file, a global using or alias declared in another file, reflection, or
26: /// operating-system behavior of a base-library call such as <c>Path.GetFullPath</c> is outside it. Repository
27: /// reads are covered by construction instead: <see cref="FindRepositoryLocators"/> keeps the shared
28: /// <c>TestRepositoryRoot</c> the only repository-root locator (DRY), and that locator refuses to resolve outside
29: /// an integration test, so a unit test that reads the checkout through any helper fails the unit run.
30: /// </summary>
31: internal static class UnitSuitePlatformScanner
32: {
33:     /// <summary>Most distinct conditional-compilation symbols one file may name; every combination is parsed.</summary>
34:     internal const int MaxConditionalSymbols = 8;
35: 
36:     private const string AssemblyOwner = "<assembly>";
37: 
38:     private const string AttributeSuffix = "Attribute";
39: 
40:     private static readonly CSharpParseOptions ParseOptions = new(LanguageVersion.Preview, DocumentationMode.None);
41: 
42:     private static readonly string[] KindOrder = ["os-check", "os-attribute", "skip", "process-host"];
43: 
44:     /// <summary>Calls, property reads and method groups on a type, matched by the type's rightmost name.</summary>
45:     private static readonly MemberRule[] MemberRules =
46:     [
47:         new("os-check", "OperatingSystem", static name => name.Length > 2 && name.StartsWith("Is", StringComparison.Ordinal) && name[2] is >= 'A' and <= 'Z'),
48:         new("os-check", "RuntimeInformation", static name => name == "IsOSPlatform"),
49:         new("skip", "Assert", static name => name is "Skip" or "SkipWhen" or "SkipUnless"),
50:         new("skip", "Skip", static name => name is "If" or "IfNot"),
51:         new("process-host", "SystemWorkspaceHostEnvironment", static name => name == "Instance"),
52:         new("process-host", "WorkspacePathNormalizer", static name => name == "Process"),
53:     ];
54: 
55:     /// <summary>
56:     /// TR-MCP-USECASE-018 (AC-006): the one definition of an xUnit skip shared by this scanner and the skip guard.
57:     /// Returns the 1-based lines, in any conditional-compilation branch and in any type or none, that hold a skip
58:     /// call (<c>Assert.Skip</c>, <c>Assert.SkipWhen</c>, <c>Assert.SkipUnless</c>, <c>Skip.If</c>,
59:     /// <c>Skip.IfNot</c>), a use of <c>SkipException</c>, a <c>SkippableFact</c> or <c>SkippableTheory</c>
60:     /// attribute, or an attribute argument that sets a property whose name starts with <c>Skip</c> (for example
61:     /// <c>Skip</c>, <c>SkipUnless</c>, <c>SkipWhen</c> or <c>SkipExceptions</c> on a test or data attribute); an
62:     /// attribute is reported on the line of its name.
63:     /// </summary>
64:     /// <param name="source">C# source text.</param>
65:     internal static IReadOnlyList<int> FindSkipLines(string source)
66:     {
67:         ArgumentNullException.ThrowIfNull(source);
68:         return ParseBranches(source)
69:             .SelectMany(FindHits)
70:             .Where(hit => hit.Kind == "skip")
71:             .Select(hit => LineOf(hit.Node))
72:             .Distinct()
73:             .Order()
74:             .ToArray();
75:     }
76: 
77:     /// <summary>
78:     /// TR-MCP-USECASE-018 (AC-006), TR-MCP-USECASE-019 (AC-008), DRY guard for repository reads: returns the 1-based
79:     /// lines, in any type and any conditional-compilation branch, of a repository-root locator other than the shared
80:     /// <c>TestRepositoryRoot</c>: a walk up (<c>.Parent</c>, <c>?.Parent</c>, <c>Directory.GetParent</c>) in a member
81:     /// that starts from <c>AppContext.BaseDirectory</c> or a <c>[CallerFilePath]</c> parameter (reported at the first
82:     /// step), a <c>Path.Combine</c> or <c>Path.Join</c> of <c>AppContext.BaseDirectory</c> with a <c>..</c> segment,
83:     /// or a read of the <c>McpRepositoryRoot</c> build metadata (the key and <c>AssemblyMetadataAttribute</c> in one
84:     /// member; the key alone, as in a comparison, is not a read).
85:     /// </summary>
86:     /// <param name="source">C# source text.</param>
87:     internal static IReadOnlyList<int> FindRepositoryLocators(string source)
88:     {
89:         ArgumentNullException.ThrowIfNull(source);
90:         return ParseBranches(source)
91:             .SelectMany(RepositoryLocatorNodes)
92:             .Select(LineOf)
93:             .Distinct()
94:             .Order()
95:             .ToArray();
96:     }
97: 
98:     /// <summary>Scans one C# source file and returns its findings in line order, then rule order.</summary>
99:     /// <param name="relativePath">Path reported with each finding.</param>
100:     /// <param name="source">File text.</param>
101:     internal static IReadOnlyList<UnitSuitePlatformFinding> Scan(string relativePath, string source)
102:     {
103:         ArgumentNullException.ThrowIfNull(relativePath);
104:         ArgumentNullException.ThrowIfNull(source);
105:         var findings = new HashSet<(int Line, string Kind, string TestClass)>();
106:         foreach (var root in ParseBranches(source))
107:         {
108:             foreach (var (node, kind) in FindHits(root))
109:             {
110:                 var testClass = FindingOwner(node);
111:                 if (testClass is not null)
112:                     findings.Add((LineOf(node), kind, testClass));
113:             }
114:         }
115: 
116:         return findings
117:             .OrderBy(finding => finding.Line)
118:             .ThenBy(finding => Array.IndexOf(KindOrder, finding.Kind))
119:             .ThenBy(finding => finding.TestClass, StringComparer.Ordinal)
120:             .Select(finding => new UnitSuitePlatformFinding(relativePath, finding.Line, finding.Kind, finding.TestClass))
121:             .ToArray();
122:     }
123: 
124:     /// <summary>
125:     /// Parses the source once for every combination of the conditional-compilation symbols it names, so code in
126:     /// every <c>#if</c>, <c>#elif</c> and <c>#else</c> branch reachable by some combination is in a tree.
127:     /// </summary>
128:     private static IReadOnlyList<CompilationUnitSyntax> ParseBranches(string source)
129:     {
130:         var none = Parse(source, []);
131:         var symbols = new SortedSet<string>(SymbolsOf(none), StringComparer.Ordinal);
132:         var known = 0;
133:         while (symbols.Count != known && symbols.Count <= MaxConditionalSymbols)
134:         {
135:             // A directive nested in a branch that is inactive with no symbols defined names its symbols here.
136:             known = symbols.Count;
137:             symbols.UnionWith(SymbolsOf(Parse(source, symbols)).ToArray());
138:         }
139: 
140:         if (symbols.Count > MaxConditionalSymbols)
141:         {
142:             throw new InvalidOperationException(
143:                 $"The source names {symbols.Count} conditional-compilation symbols; the platform scan reads every branch and supports at most {MaxConditionalSymbols}.");
144:         }
145: 
146:         var names = symbols.ToArray();
147:         var roots = new List<CompilationUnitSyntax> { none };
148:         for (var mask = 1; mask < 1 << names.Length; mask++)
149:             roots.Add(Parse(source, names.Where((_, index) => (mask & (1 << index)) != 0)));
150: 
151:         return roots;
152:     }
153: 
154:     private static CompilationUnitSyntax Parse(string source, IEnumerable<string> symbols) =>
155:         CSharpSyntaxTree.ParseText(source, ParseOptions.WithPreprocessorSymbols(symbols)).GetCompilationUnitRoot();
156: 
157:     private static IEnumerable<string> SymbolsOf(CompilationUnitSyntax root) =>
158:         root.DescendantNodes(descendIntoTrivia: true)
159:             .OfType<ConditionalDirectiveTriviaSyntax>()
160:             .SelectMany(directive => directive.Condition.DescendantNodesAndSelf().OfType<IdentifierNameSyntax>())
161:             .Select(identifier => identifier.Identifier.ValueText);
162: 
163:     /// <summary>Every rule hit in one tree, with the node it is reported on.</summary>
164:     private static IEnumerable<(SyntaxNode Node, string Kind)> FindHits(CompilationUnitSyntax root)
165:     {
166:         var scopes = new Dictionary<SyntaxNode, ImportScope>();
167:         foreach (var node in root.DescendantNodes(child => child is not UsingDirectiveSyntax))
168:         {
169:             IReadOnlyList<string> kinds = node switch
170:             {
171:                 AttributeSyntax attribute => AttributeKinds(attribute, ScopeOf(attribute, scopes).Aliases),
172:                 MemberAccessExpressionSyntax access => MemberKinds(TypeName(access.Expression, ScopeOf(access, scopes).Aliases), access.Name.Identifier.ValueText),
173:                 IdentifierNameSyntax { Identifier.ValueText: "SkipException" } => ["skip"],
174:                 IdentifierNameSyntax identifier when IsUnqualified(identifier) => StaticImportKinds(identifier.Identifier.ValueText, ScopeOf(identifier, scopes).StaticTypes),
175:                 _ => [],
176:             };
177:             if (kinds.Count > 0 && (node is AttributeSyntax || !InNameOf(node)))
178:             {
179:                 foreach (var kind in kinds)
180:                     yield return (node, kind);
181:             }
182:         }
183:     }
184: 
185:     /// <summary>The using aliases and static imports in effect at <paramref name="node"/>.</summary>
186:     private static ImportScope ScopeOf(SyntaxNode node, Dictionary<SyntaxNode, ImportScope> scopes) =>
187:         ScopeFor(node.Ancestors().First(IsImportContainer), scopes);
188: 
189:     /// <summary>
190:     /// The using aliases and static imports in effect inside <paramref name="container"/> (the file or a namespace),
191:     /// resolved the way the compiler resolves them: the file's directives, then each enclosing namespace's from the
192:     /// outermost in, an inner alias hiding an outer alias of the same name. Cached per container.
193:     /// </summary>
194:     private static ImportScope ScopeFor(SyntaxNode container, Dictionary<SyntaxNode, ImportScope> scopes)
195:     {
196:         if (scopes.TryGetValue(container, out var known))
197:             return known;
198: 
199:         var outer = container.Ancestors().FirstOrDefault(IsImportContainer);
200:         var enclosing = outer is null ? ImportScope.Empty : ScopeFor(outer, scopes);
201:         var aliases = new Dictionary<string, string>(enclosing.Aliases, StringComparer.Ordinal);
202:         var staticTypes = new HashSet<string>(enclosing.StaticTypes, StringComparer.Ordinal);
203:         var usings = container is BaseNamespaceDeclarationSyntax space ? space.Usings : ((CompilationUnitSyntax)container).Usings;
204:         foreach (var directive in usings)
205:         {
206:             var target = RightmostName(directive.NamespaceOrType);
207:             if (target is null)
208:                 continue;
209:             if (directive.Alias is not null)
210:                 aliases[directive.Alias.Name.Identifier.ValueText] = target;
211:             else if (directive.StaticKeyword.IsKind(SyntaxKind.StaticKeyword))
212:                 staticTypes.Add(target);
213:         }
214: 
215:         var scope = new ImportScope(aliases, staticTypes);
216:         scopes[container] = scope;
217:         return scope;
218:     }
