220:     private static bool IsImportContainer(SyntaxNode node) => node is CompilationUnitSyntax or BaseNamespaceDeclarationSyntax;
221: 
222:     private static IEnumerable<SyntaxNode> RepositoryLocatorNodes(CompilationUnitSyntax root)
223:     {
224:         foreach (var member in root.DescendantNodes().OfType<MemberDeclarationSyntax>()
225:                      .Where(member => member is not BaseTypeDeclarationSyntax and not BaseNamespaceDeclarationSyntax and not DelegateDeclarationSyntax))
226:         {
227:             var nodes = member.DescendantNodes().ToArray();
228:             if (nodes.Any(IsBaseDirectory) || nodes.OfType<ParameterSyntax>().Any(HasCallerFilePath))
229:             {
230:                 var step = nodes.FirstOrDefault(IsParentStep);
231:                 if (step is not null)
232:                     yield return step;
233:             }
234: 
235:             foreach (var walk in nodes.OfType<InvocationExpressionSyntax>().Where(IsRelativeWalkUp))
236:                 yield return walk;
237: 
238:             // A read of the build metadata names the attribute type and the key in the same member.
239:             if (nodes.OfType<SimpleNameSyntax>().Any(name => WithoutAttributeSuffix(name.Identifier.ValueText) == "AssemblyMetadata"))
240:             {
241:                 foreach (var literal in nodes.OfType<LiteralExpressionSyntax>().Where(literal => IsStringLiteral(literal, "McpRepositoryRoot")))
242:                     yield return literal;
243:             }
244:         }
245:     }
246: 
247:     private static bool IsBaseDirectory(SyntaxNode node) =>
248:         node is MemberAccessExpressionSyntax { Name.Identifier.ValueText: "BaseDirectory" } access
249:         && RightmostName(access.Expression) == "AppContext";
250: 
251:     private static bool HasCallerFilePath(ParameterSyntax parameter) =>
252:         parameter.AttributeLists.SelectMany(list => list.Attributes)
253:             .Any(attribute => WithoutAttributeSuffix(RightmostName(attribute.Name)) == "CallerFilePath");
254: 
255:     private static bool IsParentStep(SyntaxNode node) => node switch
256:     {
257:         MemberAccessExpressionSyntax { Name.Identifier.ValueText: "Parent" } => true,
258:         MemberBindingExpressionSyntax { Name.Identifier.ValueText: "Parent" } => true,
259:         InvocationExpressionSyntax { Expression: MemberAccessExpressionSyntax { Name.Identifier.ValueText: "GetParent" } } => true,
260:         _ => false,
261:     };
262: 
263:     private static bool IsRelativeWalkUp(InvocationExpressionSyntax invocation) =>
264:         RightmostName(invocation.Expression) is "Combine" or "Join"
265:         && invocation.ArgumentList.Arguments.Any(argument => IsBaseDirectory(argument.Expression))
266:         && invocation.ArgumentList.Arguments.Any(argument =>
267:             argument.Expression is LiteralExpressionSyntax literal
268:             && literal.IsKind(SyntaxKind.StringLiteralExpression)
269:             && literal.Token.ValueText.StartsWith("..", StringComparison.Ordinal));
