271:     private static IReadOnlyList<string> AttributeKinds(AttributeSyntax attribute, IReadOnlyDictionary<string, string> aliases)
272:     {
273:         var name = WithoutAttributeSuffix(TypeName(attribute.Name, aliases));
274:         var kinds = new List<string>();
275:         if (name is "SupportedOSPlatform" or "UnsupportedOSPlatform")
276:             kinds.Add("os-attribute");
277:         if (name is "SkippableFact" or "SkippableTheory" || SetsSkipProperty(attribute))
278:             kinds.Add("skip");
279:         return kinds;
280:     }
281: 
282:     private static IReadOnlyList<string> MemberKinds(string? typeName, string member) =>
283:         MemberRules.Where(rule => rule.Type == typeName && rule.Matches(member)).Select(rule => rule.Kind).ToArray();
284: 
285:     private static IReadOnlyList<string> StaticImportKinds(string member, IReadOnlySet<string> staticTypes) =>
286:         MemberRules.Where(rule => staticTypes.Contains(rule.Type) && rule.Matches(member)).Select(rule => rule.Kind).ToArray();
287: 
288:     private static bool SetsSkipProperty(AttributeSyntax attribute) =>
289:         attribute.ArgumentList is { } arguments
290:         && arguments.Arguments.Any(argument =>
291:             argument.NameEquals is { } nameEquals && nameEquals.Name.Identifier.ValueText.StartsWith("Skip", StringComparison.Ordinal));
292: 
293:     /// <summary>The unit test class a hit counts against, or null when it is in no test class or in an integration test.</summary>
294:     private static string? FindingOwner(SyntaxNode node)
295:     {
296:         if (node is AttributeSyntax { Parent: AttributeListSyntax { Target.Identifier.ValueText: "assembly" or "module" } })
297:             return AssemblyOwner;
298: 
299:         var testClass = node.Ancestors().OfType<TypeDeclarationSyntax>().FirstOrDefault(IsTestClass);
300:         if (testClass is null
301:             || testClass.AncestorsAndSelf().OfType<TypeDeclarationSyntax>().Any(type => HasIntegrationTrait(type.AttributeLists)))
302:         {
303:             return null;
304:         }
305: 
306:         var method = node.Ancestors().OfType<MethodDeclarationSyntax>().FirstOrDefault();
307:         if (method is not null && IsTestMethod(method) && HasIntegrationTrait(method.AttributeLists))
308:             return null;
309: 
310:         return testClass.Identifier.ValueText;
311:     }
312: 
313:     private static bool IsTestClass(TypeDeclarationSyntax type) =>
314:         type.Identifier.ValueText.EndsWith("Tests", StringComparison.Ordinal)
315:         || type.Members.OfType<MethodDeclarationSyntax>().Any(IsTestMethod);
316: 
317:     private static bool IsTestMethod(MethodDeclarationSyntax method) =>
318:         method.AttributeLists.SelectMany(list => list.Attributes).Any(attribute =>
319:             WithoutAttributeSuffix(RightmostName(attribute.Name)) is { } name
320:             && (name.EndsWith("Fact", StringComparison.Ordinal) || name.EndsWith("Theory", StringComparison.Ordinal)));
321: 
322:     private static bool HasIntegrationTrait(SyntaxList<AttributeListSyntax> lists) =>
323:         lists.SelectMany(list => list.Attributes).Any(attribute =>
324:             WithoutAttributeSuffix(RightmostName(attribute.Name)) == "Trait"
325:             && attribute.ArgumentList is { Arguments.Count: >= 2 } arguments
326:             && IsStringLiteral(arguments.Arguments[0].Expression, "Category")
327:             && IsStringLiteral(arguments.Arguments[1].Expression, "Integration"));
328: 
329:     private static bool IsStringLiteral(ExpressionSyntax expression, string value) =>
330:         expression is LiteralExpressionSyntax literal
331:         && literal.IsKind(SyntaxKind.StringLiteralExpression)
332:         && literal.Token.ValueText == value;
333: 
334:     /// <summary>True for a name that is not the member or right-hand part of a qualified name or access.</summary>
335:     private static bool IsUnqualified(IdentifierNameSyntax identifier) => identifier.Parent switch
336:     {
337:         MemberAccessExpressionSyntax access => access.Name != identifier,
338:         QualifiedNameSyntax qualified => qualified.Right != identifier,
339:         AliasQualifiedNameSyntax => false,
340:         MemberBindingExpressionSyntax => false,
341:         NameEqualsSyntax or NameColonSyntax => false,
342:         _ => true,
343:     };
344: 
345:     private static bool InNameOf(SyntaxNode node) =>
346:         node.Ancestors().Any(ancestor =>
347:             ancestor is InvocationExpressionSyntax { Expression: IdentifierNameSyntax { Identifier.ValueText: "nameof" } });
348: 
349:     /// <summary>The rightmost name of a type or receiver expression, resolving a using alias in scope.</summary>
350:     private static string? TypeName(SyntaxNode node, IReadOnlyDictionary<string, string> aliases) =>
351:         node is IdentifierNameSyntax identifier && aliases.TryGetValue(identifier.Identifier.ValueText, out var target)
352:             ? target
353:             : RightmostName(node);
354: 
355:     private static string? RightmostName(SyntaxNode? node) => node switch
356:     {
357:         SimpleNameSyntax simple => simple.Identifier.ValueText,
358:         QualifiedNameSyntax qualified => qualified.Right.Identifier.ValueText,
359:         AliasQualifiedNameSyntax aliasQualified => aliasQualified.Name.Identifier.ValueText,
360:         MemberAccessExpressionSyntax access => access.Name.Identifier.ValueText,
361:         _ => null,
362:     };
363: 
364:     private static string? WithoutAttributeSuffix(string? name) =>
365:         name is not null && name.Length > AttributeSuffix.Length && name.EndsWith(AttributeSuffix, StringComparison.Ordinal)
366:             ? name[..^AttributeSuffix.Length]
367:             : name;
368: 
369:     private static int LineOf(SyntaxNode node) => node.GetLocation().GetLineSpan().StartLinePosition.Line + 1;
370: 
371:     private sealed record MemberRule(string Kind, string Type, Func<string, bool> Matches);
372: 
373:     /// <summary>Using aliases (alias to the target's rightmost name) and static-import types in effect in one scope.</summary>
374:     private sealed record ImportScope(IReadOnlyDictionary<string, string> Aliases, IReadOnlySet<string> StaticTypes)
375:     {
376:         internal static readonly ImportScope Empty =
377:             new(new Dictionary<string, string>(StringComparer.Ordinal), new HashSet<string>(StringComparer.Ordinal));
378:     }
379: }
