189:     /// <summary>
190:     /// The using aliases and static imports in effect inside <paramref name="container"/> (the file or a namespace),
191:     /// resolved the way the compiler resolves them: the file's directives, then each enclosing namespace's from the
192:     /// outermost in, an inner alias hiding an outer alias of the same name. Cached per container.
193:     /// </summary>
194:     private static ImportScope ScopeFor(SyntaxNode container, Dictionary<SyntaxNode, ImportScope> scopes)
195:     {
196:         if (scopes.TryGetValue(container, out var known))
197:             return known;
198: 
199:         var outer = container.Ancestors().FirstOrDefault(IsImportContainer);
200:         var enclosing = outer is null ? ImportScope.Empty : ScopeFor(outer, scopes);
201:         var aliases = new Dictionary<string, string>(enclosing.Aliases, StringComparer.Ordinal);
202:         var staticTypes = new HashSet<string>(enclosing.StaticTypes, StringComparer.Ordinal);
203:         var usings = container is BaseNamespaceDeclarationSyntax space ? space.Usings : ((CompilationUnitSyntax)container).Usings;
204:         foreach (var directive in usings)
205:         {
206:             var target = RightmostName(directive.NamespaceOrType);
207:             if (target is null)
208:                 continue;
209:             if (directive.Alias is not null)
210:                 aliases[directive.Alias.Name.Identifier.ValueText] = target;
211:             else if (directive.StaticKeyword.IsKind(SyntaxKind.StaticKeyword))
212:                 staticTypes.Add(target);
213:         }
214: 
215:         var scope = new ImportScope(aliases, staticTypes);
216:         scopes[container] = scope;
217:         return scope;
218:     }
