251:     private static bool HasCallerFilePath(ParameterSyntax parameter) =>
252:         parameter.AttributeLists.SelectMany(list => list.Attributes)
253:             .Any(attribute => WithoutAttributeSuffix(RightmostName(attribute.Name)) == "CallerFilePath");
