255:     private static bool IsParentStep(SyntaxNode node) => node switch
256:     {
257:         MemberAccessExpressionSyntax { Name.Identifier.ValueText: "Parent" } => true,
258:         MemberBindingExpressionSyntax { Name.Identifier.ValueText: "Parent" } => true,
259:         InvocationExpressionSyntax { Expression: MemberAccessExpressionSyntax { Name.Identifier.ValueText: "GetParent" } } => true,
260:         _ => false,
261:     };
