263:     private static bool IsRelativeWalkUp(InvocationExpressionSyntax invocation) =>
264:         RightmostName(invocation.Expression) is "Combine" or "Join"
265:         && invocation.ArgumentList.Arguments.Any(argument => IsBaseDirectory(argument.Expression))
266:         && invocation.ArgumentList.Arguments.Any(argument =>
267:             argument.Expression is LiteralExpressionSyntax literal
268:             && literal.IsKind(SyntaxKind.StringLiteralExpression)
269:             && literal.Token.ValueText.StartsWith("..", StringComparison.Ordinal));
